script:
html { scroll-behavior: smooth; color-scheme: dark; }
::selection { background: #7C5CFF; color: #FFFFFF; }
.au-glow { background: radial-gradient(60% 46% at 50% 0%, rgba(124, 92, 255, 0.32), transparent 70%); }
.au-grad, .au-grad * { background: linear-gradient(100deg, #B3A1FF 10%, #6FE7F0 90%); -webkit-background-clip: text; background-clip: text; color: transparent; }
input::placeholder, textarea::placeholder { color: #5E637A; }
input:focus, textarea:focus { border-color: #7C5CFF; outline: none; }
